"""Начальные фундаментальные проблемы по прямому поручению автора; без новых измерений."""
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.recovery_research_service_20261027 import read,write,sha,now

def source(path,claim):
    assert (ROOT/path).is_file(),path
    return dict(source=path,sha256=sha(ROOT/path),claim=claim)

def problem(ident,title,status,component,fact,hypotheses,next_check,closure,evidence,cards=(),legacy=()):
    return dict(id=ident,title=title,status=status,component=component,fact=fact,hypotheses=hypotheses,next_check=next_check,
        closure=closure,evidence=evidence,cards=list(cards),legacy=list(legacy),first_seen='2026-10-28',updated='2026-10-28',
        cases=[dict(date='2026-10-28',fact=fact,evidence=[e['source'] for e in evidence])])

